    const flick = 0.72 + 0.18 * Math.sin(G.menuT * 3 + l.phase) + 0.1 * Math.sin(G.menuT * 13 + l.phase * 2);
    ctx.globalAlpha = 0.4 * flick;
    ctx.drawImage(lightSprite, l.x - 215, l.y - 215, 430, 430);
  }
  if (G.player && G.state !== 'menu') {
    ctx.globalAlpha = 0.16;
    ctx.drawImage(lightSprite, G.player.x - 190, G.player.y - 190, 380, 380);
  }
  ctx.restore();

