    ctx.globalAlpha = 0.06;
    const t = G.menuT * 12;
    ctx.drawImage(fogSprite, ARENA.w / 2 - 700 + Math.sin(t * 0.01) * 200, ARENA.h / 2 - 500, 1400, 1000);
