    const flick = 0.8 + 0.2 * Math.sin(G.menuT * 9 + l.phase);
    ctx.globalAlpha = 0.11 * flick;
    ctx.drawImage(lightSprite, l.x - 90, l.y - 90, 180, 180);
  }
  ctx.restore();
}

