import { chromium } from 'playwright';

const browser = await chromium.launch({
  headless: true,
  executablePath: '/usr/bin/google-chrome',
  args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader']
});
const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
await page.waitForTimeout(700);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/menu.jpg', type: 'jpeg', quality: 72 });
console.log('menu info', await page.evaluate(() => window.__RATO.info()));
await page.evaluate(() => window.__RATO.start(0));
await page.waitForTimeout(1200);
console.log('game info', await page.evaluate(() => window.__RATO.info()));
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/game1.jpg', type: 'jpeg', quality: 72 });
// measure fps over 3s via rAF
const fps = await page.evaluate(() => new Promise(resolve => {
  let n = 0; const t0 = performance.now();
  function tick() { n++; if (performance.now() - t0 < 3000) requestAnimationFrame(tick); else resolve(n / ((performance.now() - t0) / 1000)); }
  requestAnimationFrame(tick);
}));
console.log('fps', fps.toFixed(1));
console.log('errors', errors);
await browser.close();

