43: function updateMovement(dt) {
44:   const p = G.player;
45:   let mx = 0, my = 0;
46:   const k = input.keys;
47:   if (k.has('a') || k.has('arrowleft')) mx -= 1;
48:   if (k.has('d') || k.has('arrowright')) mx += 1;
49:   if (k.has('w') || k.has('arrowup')) my -= 1;
50:   if (k.has('s') || k.has('arrowdown')) my += 1;
51:   mx += input.joy.x;
52:   my += input.joy.y;
53:   const len = Math.hypot(mx, my);
54:   if (len > 1) { mx /= len; my /= len; }
55:   p.moving = len > 0.08;
56:   if (p.moving) {
57:     p.x += mx * p.speed * p.speedMult * dt;
58:     p.y += my * p.speed * p.speedMult * dt;
59:     p.moveAngle = Math.atan2(my, mx);
60:     p.walkT += dt * (5 + Math.hypot(mx, my) * 5);
61:     if (Math.random() < dt * 8) {
62:       spawnParticles(p.x - mx * 12, p.y + 10, 'rgba(160,150,130,0.28)', 1, 12, 0.35, 3);
63:     }
64:   }
65:   p.x = clamp(p.x, ARENA.pad, ARENA.w - ARENA.pad);
66:   p.y = clamp(p.y, ARENA.pad, ARENA.h - ARENA.pad);
