143:       if (shots > 1) a += (s === 0 ? -1 : 1) * 0.045;
144:       const mx = p.x + Math.cos(a) * muzzleDist;
145:       const my = p.y + Math.sin(a) * muzzleDist;
146:       G.bullets.push({
147:         x: mx, y: my, px: mx, py: my,
148:         vx: Math.cos(a) * def.speed,
149:         vy: Math.sin(a) * def.speed,
150:         dmg: baseDmg,
151:         r: def.bulletR,
152:         life: (def.range * p.rangeMult) / def.speed + 0.04,
153:         color: superOn ? '#ffe27a' : def.color,
154:         burn: p.cigar || p.fusion,
155:         burnPower: p.fusion ? 2.1 : 1,
156:         heavy: def.id === 'eagle'
157:       });
158:     }
159:   }
