161:   // muzzle sparks
162:   const mx = p.x + Math.cos(p.aim) * 30;
163:   const my = p.y + Math.sin(p.aim) * 30;
164:   spawnParticles(mx, my, superOn ? '#ffd34d' : def.color, def.id === 'shotgun' ? 9 : 4, 190, 0.18, 2.4);
165:   spawnParticles(mx, my, 'rgba(255,255,255,0.8)', 2, 90, 0.1, 1.6);
166:   addFloat(mx + rand(-6, 6), my - 8, 'BANG', superOn ? '#ffe27a' : 'rgba(255,220,160,0.55)', def.id === 'shotgun' ? 13 : 11, 0.35);
167:   audio.sfx(def.sfx);
168: 
169:   if (ws.ammo <= 0) startReload();
