172: /* --------------------------------------------------------------- enemies */
173: function hpScale() {
174:   return (1 + G.time * 0.011) * Math.pow(2, G.loop);
175: }
176: function speedScale() {
177:   return (1 + Math.min(0.4, G.time / 420)) * Math.pow(1.1, G.loop);
178: }
