180: const ENEMY_TYPES = {
181:   trap: { r: 16, hp: 28, speed: 158, damage: 1, xp: 14, cd: 0.72 },
182:   cat:  { r: 24, hp: 112, speed: 97, damage: 2, xp: 42, cd: 1.0 },
183:   boss: { r: 52, hp: 1500, speed: 63, damage: 2, xp: 420, cd: 1.0 }
184: };
