186: function makeEnemy(type, x, y) {
187:   const t = ENEMY_TYPES[type];
188:   const scale = hpScale();
189:   let hp = t.hp * scale;
190:   if (type === 'boss') hp = (1000 + G.level * 130) * Math.pow(2, G.loop) * (1 + G.time * 0.002);
191:   return {
192:     type, x, y, r: t.r, hp, maxHp: hp,
193:     speed: t.speed * speedScale(),
194:     damage: t.damage, xp: t.xp,
195:     attackT: rand(0.2, 0.9), attackCd: t.cd,
196:     flash: 0, dead: false, burn: 0, burnTick: 0, burnDps: 0,
197:     isBoss: type === 'boss', phase: 0, summon1: false, summon2: false,
198:     wobble: rand(0, TAU), bob: rand(0, TAU), enraged: false
199:   };
200: }
