202: function spawnEnemy(type) {
203:   if (G.enemies.length >= 110) return;
204:   const p = G.player;
205:   const preferred = type || (Math.random() < catChance() ? 'cat' : 'trap');
206:   const viewW = W / G.camera.zoom, viewH = H / G.camera.zoom;
207:   const minR = Math.max(viewW, viewH) * 0.54 + 90;
208:   let x = 0, y = 0, ok = false;
209:   for (let i = 0; i < 18; i++) {
210:     const a = rand(0, TAU);
211:     const r = minR + rand(0, 220);
212:     x = clamp(p.x + Math.cos(a) * r, ARENA.pad + 24, ARENA.w - ARENA.pad - 24);
213:     y = clamp(p.y + Math.sin(a) * r, ARENA.pad + 24, ARENA.h - ARENA.pad - 24);
214:     if (dist(x, y, p.x, p.y) > minR * 0.72) { ok = true; break; }
215:   }
216:   if (!ok) {
217:     for (let i = 0; i < 20; i++) {
218:       x = rand(ARENA.pad + 40, ARENA.w - ARENA.pad - 40);
219:       y = rand(ARENA.pad + 40, ARENA.h - ARENA.pad - 40);
220:       if (dist(x, y, p.x, p.y) > 420) break;
221:     }
222:   }
223:   G.enemies.push(makeEnemy(preferred, x, y));
224: }
