255: function updateEnemies(dt) {
256:   const p = G.player;
257:   for (const e of G.enemies) {
258:     if (e.dead) continue;
259:     if (e.flash > 0) e.flash -= dt;
260: 
261:     if (e.burn > 0) {
262:       e.burn -= dt;
263:       e.burnTick -= dt;
264:       if (e.burnTick <= 0) {
265:         e.burnTick = 0.34;
266:         e.hp -= e.burnDps * 0.34;
267:         addFloat(e.x + rand(-10, 10), e.y - e.r - 10, Math.round(e.burnDps * 0.34), '#ff9a4d', 10, 0.5);
268:         spawnParticles(e.x + rand(-8, 8), e.y + rand(-8, 8), '#ff8a3c', 1, 45, 0.3, 2.5);
269:         if (e.hp <= 0) { killEnemy(e); continue; }
270:       }
271:       if (Math.random() < dt * 12) spawnParticles(e.x + rand(-10, 10), e.y + rand(-10, 10), 'rgba(255,120,40,0.8)', 1, 28, 0.45, 2.2);
272:     }
273: 
274:     if (e.isBoss) {
275:       updateBoss(e, dt);
276:       continue;
277:     }
278: 
279:     const d = dist(e.x, e.y, p.x, p.y);
280:     const a = angleTo(e.x, e.y, p.x, p.y);
281:     const wob = Math.sin(G.time * 7 + e.wobble) * (e.type === 'trap' ? 0.32 : 0.11);
282:     if (d > e.r + p.r - 2) {
283:       const sp = e.speed * (e.type === 'trap' ? 1.06 : 1);
284:       e.x += Math.cos(a + wob) * sp * dt;
285:       e.y += Math.sin(a + wob) * sp * dt;
286:     }
287:     e.bob += dt * (e.type === 'trap' ? 12 : 5);
288: 
289:     if (e.attackT > 0) e.attackT -= dt;
290:     if (d < e.r + p.r + 5 && e.attackT <= 0) {
291:       e.attackT = e.attackCd;
292:       hurtPlayer(e.damage);
293:       e.x -= Math.cos(a) * 14;
294:       e.y -= Math.sin(a) * 14;
295:     }
296:   }
297: 
298:   // separation
299:   const list = G.enemies;
300:   for (let i = 0; i < list.length; i++) {
301:     const a = list[i];
302:     if (a.dead) continue;
303:     for (let j = i + 1; j < list.length; j++) {
304:       const b = list[j];
305:       if (b.dead) continue;
306:       const min = (a.r + b.r) * 0.9;
307:       const dx = b.x - a.x, dy = b.y - a.y;
308:       const d2 = dx * dx + dy * dy;
309:       if (d2 > 0.01 && d2 < min * min) {
310:         const d = Math.sqrt(d2);
311:         const push = (min - d) * 0.5;
312:         const nx = dx / d, ny = dy / d;
313:         a.x -= nx * push; a.y -= ny * push;
314:         b.x += nx * push; b.y += ny * push;
315:       }
316:     }
317:     a.x = clamp(a.x, ARENA.pad + 12, ARENA.w - ARENA.pad - 12);
318:     a.y = clamp(a.y, ARENA.pad + 12, ARENA.h - ARENA.pad - 12);
319:   }
320: }
