322: function updateBoss(e, dt) {
323:   const p = G.player;
324:   const d = dist(e.x, e.y, p.x, p.y);
325:   const a = angleTo(e.x, e.y, p.x, p.y);
326:   if (e.hp < e.maxHp * 0.66 && !e.summon1) { e.summon1 = true; summonCats(e, 3); }
327:   if (e.hp < e.maxHp * 0.33 && !e.summon2) { e.summon2 = true; e.enraged = true; summonCats(e, 4); }
328:   const sp = e.speed * (e.enraged ? 1.35 : 1);
329:   if (d > 260) {
330:     e.x += Math.cos(a) * sp * dt;
331:     e.y += Math.sin(a) * sp * dt;
332:   } else if (d < 165) {
333:     e.x -= Math.cos(a) * sp * dt;
334:     e.y -= Math.sin(a) * sp * dt;
335:   } else {
336:     e.x += Math.cos(a + Math.PI / 2) * sp * 0.55 * dt;
337:     e.y += Math.sin(a + Math.PI / 2) * sp * 0.55 * dt;
338:   }
339:   e.bob += dt * 3;
340: 
341:   e.attackT -= dt;
342:   if (e.attackT <= 0 && d < 900) {
343:     e.attackT = e.enraged ? 1.25 : 1.8;
