357:   if (d < e.r + p.r + 6 && e.attackT < e.attackCd - 0.12) {
358:     // contact is handled by the generic attack clock: give it a dedicated nudge
359:     if (!e._touchT || G.time - e._touchT > 1.1) {
360:       e._touchT = G.time;
361:       hurtPlayer(2);
362:     }
363:   }
