367: function segmentHitsCircle(x1, y1, x2, y2, cx, cy, r) {
368:   const dx = x2 - x1, dy = y2 - y1;
369:   const len2 = dx * dx + dy * dy;
370:   let t = 0;
371:   if (len2 > 0.0001) t = clamp(((cx - x1) * dx + (cy - y1) * dy) / len2, 0, 1);
372:   const px = x1 + dx * t, py = y1 + dy * t;
373:   const ddx = px - cx, ddy = py - cy;
374:   return ddx * ddx + ddy * ddy <= r * r;
375: }
