377: function updateBullets(dt) {
378:   const p = G.player;
379:   for (const b of G.bullets) {
380:     b.px = b.x; b.py = b.y;
381:     b.x += b.vx * dt;
382:     b.y += b.vy * dt;
383:     b.life -= dt;
384:     if (Math.random() < 0.55) {
385:       spawnParticles(b.x, b.y, hexA(b.color, 0.5), 1, 18, 0.16, b.heavy ? 2.4 : 1.7);
386:     }
