388:       b.dead = true;
389:       continue;
390:     }
391:     for (const e of G.enemies) {
392:       if (e.dead) continue;
393:       if (segmentHitsCircle(b.px, b.py, b.x, b.y, e.x, e.y, e.r + b.r)) {
394:         hitEnemy(e, b);
395:         b.dead = true;
396:         break;
397:       }
398:     }
399:   }
400:   G.bullets = G.bullets.filter((b) => !b.dead);
401: 
402:   for (const b of G.ebullets) {
403:     const px = b.x, py = b.y;
404:     b.x += b.vx * dt;
405:     b.y += b.vy * dt;
406:     b.life -= dt;
407:     b.rot = Math.atan2(b.vy, b.vx);
408:     if (b.life <= 0) { b.dead = true; continue; }
409:     if (segmentHitsCircle(px, py, b.x, b.y, p.x, p.y, p.r + b.r)) {
410:       b.dead = true;
411:       hurtPlayer(b.dmg);
412:       spawnParticles(b.x, b.y, '#ff6b3d', 8, 130, 0.35, 2.5);
