418: function hitEnemy(e, b) {
419:   if (e.dead) return;
420:   const crit = Math.random() < 0.08;
421:   const dmg = b.dmg * (crit ? 2 : 1);
422:   e.hp -= dmg;
423:   e.flash = 0.1;
424:   addFloat(e.x + rand(-9, 9), e.y - e.r - 8, Math.round(dmg), crit ? '#ffe27a' : '#fff3d4', crit ? 17 : 12, 0.55);
425:   spawnParticles(b.x, b.y, crit ? '#ffe27a' : '#ffcf92', crit ? 7 : 3, 155, 0.3, 2.2);
426:   spawnParticles(b.x, b.y, 'rgba(255,255,255,0.9)', 1, 80, 0.15, 1.4);
427:   if (b.burn) {
428:     e.burn = Math.max(e.burn, 3);
429:     e.burnTick = Math.min(e.burnTick || 0.34, 0.2);
430:     e.burnDps = Math.max(e.burnDps, b.dmg * (b.burnPower || 1) * 0.42);
431:   }
432:   if (G.time - lastHitSfx > 0.045) {
433:     lastHitSfx = G.time;
434:     audio.sfx(crit ? 'crit' : 'hit');
435:   }
436:   if (e.hp <= 0) killEnemy(e);
