import pw from '/home/runner/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/index.js';
const { chromium } = pw;
const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/google-chrome', args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
const context = await browser.newContext({ viewport: { width: 1280, height: 720 } });
const page = await context.newPage();
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
const info = () => page.evaluate(() => window.__RATO.info());
const state = () => page.evaluate(() => window.__RATO.state());

await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
// choose shotgun and start via click
await page.locator('.choice').nth(1).click();
await page.locator('#btn-start').click();
await page.waitForTimeout(400);
console.log('started shotgun', await info());

// Ammo fires automatically when enemy near; spawn an enemy close
await page.evaluate(() => { const p = window.__RATO.player(); __RATO.spawn('cat'); const e = G.enemies[G.enemies.length - 1]; e.x = p.x + 150; e.y = p.y; });
await page.waitForTimeout(1200);
console.log('ammo after fire', await page.evaluate(() => window.__RATO.player().weapons.map(w => w.ammo)));

// reload key
await page.keyboard.press('r');
await page.waitForTimeout(300);
console.log('reloading', await page.evaluate(() => window.__RATO.player().weapons.map(w => w.reloading)));
await page.waitForTimeout(2400);
console.log('reloaded ammo', await page.evaluate(() => window.__RATO.player().weapons.map(w => w.ammo)));

// move with keyboard
const p0 = await page.evaluate(() => ({ x: window.__RATO.player().x, y: window.__RATO.player().y }));
await page.keyboard.down('d');
await page.waitForTimeout(800);
await page.keyboard.up('d');
const p1 = await page.evaluate(() => ({ x: window.__RATO.player().x, y: window.__RATO.player().y }));
console.log('keyboard move dx', Math.round(p1.x - p0.x));

// switch locked weapon no-op then unlock all and cycle
await page.keyboard.press('3');
console.log('locked switch', await page.evaluate(() => window.__RATO.player().weapon));
await page.evaluate(() => { const p = window.__RATO.player(); p.weapons.forEach(w => w.unlocked = true); });
await page.keyboard.press('3');
console.log('switch 3', await page.evaluate(() => window.__RATO.player().weapon));
await page.keyboard.press('1');
console.log('switch 1', await page.evaluate(() => window.__RATO.player().weapon));

// boss phases
await page.evaluate(() => { window.__RATO.god(true); window.__RATO.boss(); });
await page.waitForTimeout(400);
console.log('boss spawned', await info());
await page.evaluate(() => { G.boss.hp = G.boss.maxHp * 0.6; });
await page.waitForTimeout(500);
console.log('after phase1', await page.evaluate(() => ({ cats: G.enemies.filter(e => e.type === 'cat').length, summon1: G.boss && G.boss.summon1 })));
await page.evaluate(() => { G.boss.hp = G.boss.maxHp * 0.25; });
await page.waitForTimeout(500);
console.log('after phase2', await page.evaluate(() => ({ cats: G.enemies.filter(e => e.type === 'cat').length, summon2: G.boss && G.boss.summon2, enraged: G.boss && G.boss.enraged })));
await page.evaluate(() => { window.__RATO.clear(); });
await page.waitForTimeout(400);
console.log('boss reward', await page.evaluate(() => ({ boss: !!G.boss, skills: window.__RATO.player().skills, score: G.score })));

// pause stats via button and key resume
await page.locator('#btn-pause').click();
await page.waitForTimeout(200);
console.log('pause stats text', (await page.locator('#pause-stats').innerText()).replace(/\n/g, ' | '));
await page.keyboard.press('p');
await page.waitForTimeout(200);
console.log('resume key state', await state());

// sound toggle persistence
await page.locator('#btn-sound').click();
console.log('muted', await page.evaluate(() => ({ muted: G.muted, stored: localStorage.getItem('rato_muted') })));
await page.locator('#btn-sound').click();

// game over -> new record, retry and menu
await page.evaluate(() => window.__RATO.die());
await page.waitForTimeout(2200);
console.log('gameover state', await state());
console.log('record line', await page.locator('#go-record').textContent(), 'best', await page.evaluate(() => G.best));
await page.locator('#btn-retry').click();
await page.waitForTimeout(400);
console.log('retry', await state(), await info());
await page.locator('#btn-pause').click();
await page.waitForTimeout(200);
await page.locator('#btn-quit').click();
await page.waitForTimeout(400);
console.log('menu', await state(), 'best label', await page.locator('#menu-best').textContent());
console.log('errors', errors);
await browser.close();

