async function fps(label) {
  const r = await page.evaluate(() => new Promise(res => {
    let n = 0; const t0 = performance.now();
    function tick() { n++; if (performance.now() - t0 < 3000) requestAnimationFrame(tick); else res({ fps: n / ((performance.now() - t0) / 1000), menuT: G.menuT, time: G.time, enemies: G.enemies.length }); }
    requestAnimationFrame(tick);
  }));
  console.log(label, r);
}
await fps('idle');
await page.keyboard.down('d');
const t0 = await page.evaluate(() => ({ time: G.time, x: __RATO.player().x }));
await page.waitForTimeout(1000);
const t1 = await page.evaluate(() => ({ time: G.time, x: __RATO.player().x, menuT: G.menuT }));
await page.keyboard.up('d');
console.log('dt', t1.time - t0.time, 'dx', t1.x - t0.x);
await page.waitForTimeout(500);
await fps('after');
console.log('raf count', await page.evaluate(() => new Promise(res => { let n=0; const s=performance.now(); function f(){n++; if(performance.now()-s<1000) requestAnimationFrame(f); else res(n);} requestAnimationFrame(f); })));
await browser.close();

